ext, destaque boolean)), inserted as (insert into public.conteudos_comunidade(titulo,subtitulo,corpo,autor_nome,fonte_nome,tags,categoria,tipo,material_url,idioma,imagem_url,aprovado,moderation_status,destaque) select i.titulo,i.subtitulo,i.corpo,i.autor_nome,i.fonte_nome,i.tags,i.categoria,i.tipo,i.material_url,i.idioma,i.imagem_url,i.aprovado,i.moderation_status,i.destaque from incoming i where not exists(select 1 from public.conteudos_comunidade c where split_part(c.material_url,'?',1)=split_part(i.material_url,'?',1)) returning id,titulo,material_url) select jsonb_agg(row_to_json(inserted)) as inserted from inserted;
